#==================================================================================
# * 1.0 e Recombination Energetics of 4Au/3TiO2 at PBE+U+D3 level *
# * Script was generated by Drew M. Glenna !!! *
#==================================================================================
import numpy as np
from ase.io import read, write
from ase.units import Bohr
from ase.dft.kpoints import monkhorst_pack
from gpaw import GPAW, FermiDirac, Davidson, MixerDif, PoissonSolver
from gpaw.cdft.cdft import CDFT
# from ase.calculators.dftd3 import DFTD3
from gpaw.cdft.cdft_coupling import CouplingParameters

# =================================================================================
# Import structure and set up calculations
# =================================================================================
sys = read("i.0.50.vasp")
sys.pbc = (True, True, False)                        # periodic boundary conditions
kp = monkhorst_pack((1, 1, 1))                                       # k-point grid
total_magmom = 0.0                                  # set the total magnetic moment
sys.set_initial_magnetic_moments([total_magmom / len(sys)] * len(sys))    # initial
fp = 'E.txt'                                             # make an Energy .txt file

# =================================================================================
# Set up initial and final state calculations
# =================================================================================
# initial state scf calculator
dfti = GPAW(
    h=0.20,                                              # grid spacing in Angstrom
    mode='fd',                                             # finite difference mode
    charge=0,                                          # total charge of the system
    xc='PBE',                                     # exchange correlation functional
    kpts=kp,                                                     # set k-point grid
    symmetry='off',                                    # set symmetry of the system
    occupations=FermiDirac(0.1, fixmagmom=False),                 # smearing method
    setups={'Ti': ':d,7.0'},      # PAW datasets with U of 7.0 eV for Ti d orbitals
    eigensolver=Davidson(3),          # eigensolver with diagonalization iterations
    spinpol=True,                                      # spin-polarized calculation
    mixer=MixerDif(beta=0.01,                           # linear mixing coefficient
                   nmaxold=1,                               # of old densities used
                   weight=100.0,                            # density mixing weight
                   beta_m=0.01,                # linear magnetic mixing coefficient
                   nmaxold_m=8,                    # of old magnetic densities used
                   weight_m=100.0),                # magnetic density mixing weight
    maxiter=1500,                        # Set the maximum number of SCF iterations
    txt=f'i.txt',                                                # output .txt file
    convergence={                                            # convergence criteria
        'eigenstates': 1.0e-10,                                   # eV^2 / electron
        'density': 1.0e-5,                                   # electrons / electron
        'energy': 1.0e-6},                                          # eV / electron
    poissonsolver = PoissonSolver(dipolelayer='xy', name='fd', relax='GS'))

# initial state cDFT calculator
Vc=[2.00, -2.00]                                             # initial guess for Vc
b=[1.00, 1.00]                                          # Vc bounds for each region
bound=[(ii-b[cc], ii+b[cc]) for cc, ii in enumerate(Vc)]         # set bounds on Vc
cdfti = CDFT(
    calc=dfti,
    atoms=sys,
    charge_regions=[[72, 73, 74, 75], list(range(0, 72))],    # Constrained regions
    charges=[1.0, -1.0],            # constrain +1.0 and -1.0 charge in Au and TiO2
    charge_coefs=Vc,                                         # initial guess for Vc
    bounds=bound,                                                       # Vc bounds
    mu={'Au': 0.61, 'Ti': 0.82, 'O': 0.70},                      # width parameters
    method='SLSQP',                                        # Vc optimization method
    txt=f'i.cdft',                                               # CDFT output file
    forces='fd',
    tol=1e-6,
    minimizer_options={'gtol': 0.01})                   # charge tolerance for CDFT

# Get initial state dft energy
sys.calc = cdfti
cdft_i = sys.get_potential_energy()
sys.calc.write('i.gpw', mode='all')

# Electron density cube file for Bader charge analysis
rho = sys.calc.get_all_electron_density(gridrefinement=4)
write('i.cube', sys, data=rho * Bohr**3)

# Get number of electrons on atoms
nei = 'nei.txt'                              # make a number of electrons .txt file
ne = sys.calc.get_number_of_electrons_on_atoms()
with open(nei, 'w') as f:
    for e in enumerate(ne):
        f.write(f"{e}\n")

# final state scf calculator
dftf = GPAW(
    h=0.20,                                              # grid spacing in Angstrom
    mode='fd',                                             # finite difference mode
    charge=0,                                          # total charge of the system
    xc='PBE',                                     # exchange correlation functional
    kpts=kp,                                                     # set k-point grid
    symmetry='off',                                    # set symmetry of the system
    occupations=FermiDirac(0.1, fixmagmom=False),                 # smearing method
    setups={'Ti': ':d,7.0'},      # PAW datasets with U of 7.0 eV for Ti d orbitals
    eigensolver=Davidson(3),          # eigensolver with diagonalization iterations
    spinpol=True,                                      # spin-polarized calculation
    mixer=MixerDif(beta=0.01,                           # linear mixing coefficient
                   nmaxold=1,                               # of old densities used
                   weight=100.0,                            # density mixing weight
                   beta_m=0.01,                # linear magnetic mixing coefficient
                   nmaxold_m=8,                    # of old magnetic densities used
                   weight_m=100.0),                # magnetic density mixing weight
    maxiter=1500,                        # Set the maximum number of SCF iterations
    txt=f'f.txt',                                                # output .txt file
    convergence={                                            # convergence criteria
        'eigenstates': 1.0e-10,                                   # eV^2 / electron
        'density': 1.0e-5,                                   # electrons / electron
        'energy': 1.0e-6},                                          # eV / electron
    poissonsolver = PoissonSolver(dipolelayer='xy', name='fd', relax='GS'))

# final state cDFT calculator
Vc=[-1.00, 1.00]                                             # initial guess for Vc
b=[1.00, 1.00]                                          # Vc bounds for each region
bound=[(ii-b[cc], ii+b[cc]) for cc, ii in enumerate(Vc)]         # set bounds on Vc
cdftf = CDFT(
    calc=dftf,
    atoms=sys,
    charge_regions=[[72, 73, 74, 75], list(range(0, 72))],    # Constrained regions
    charges=[0.0, 0.0],               # constrain 0.0 and 0.0 charge in Au and TiO2
    charge_coefs=Vc,                                         # initial guess for Vc
    bounds=bound,                                                       # Vc bounds
    mu={'Au': 0.61, 'Ti': 0.82, 'O': 0.70},                      # width parameters
    method='SLSQP',                                        # Vc optimization method
    txt=f'f.cdft',                                               # CDFT output file
    forces='fd',
    tol=1e-6,
    minimizer_options={'gtol': 0.01})                   # charge tolerance for CDFT

# Get final state cdft energy
sys.calc = cdftf
cdft_f = sys.get_potential_energy()
sys.calc.write('f.gpw', mode='all')

# Electron density cube file for Bader charge analysis
rho = sys.calc.get_all_electron_density(gridrefinement=4)
write('f.cube', sys, data=rho * Bohr**3)

# Get number of electrons on atoms
nef = 'nef.txt'                              # make a number of electrons .txt file
ne = sys.calc.get_number_of_electrons_on_atoms()
with open(nef, 'w') as f:
    for e in enumerate(ne):
        f.write(f"{e}\n")

# Ground state scf calculator
dft = GPAW(
    h=0.20,                                              # grid spacing in Angstrom
    mode='fd',                                             # finite difference mode
    charge=0,                                          # total charge of the system
    xc='PBE',                                     # exchange correlation functional
    kpts=kp,                                                     # set k-point grid
    symmetry='off',                                    # set symmetry of the system
    occupations=FermiDirac(0.1, fixmagmom=False),                 # smearing method
    setups={'Ti': ':d,7.0'},      # PAW datasets with U of 7.0 eV for Ti d orbitals
    eigensolver=Davidson(3),          # eigensolver with diagonalization iterations
    spinpol=True,                                      # spin-polarized calculation
    mixer=MixerDif(beta=0.01,                           # linear mixing coefficient
                   nmaxold=1,                               # of old densities used
                   weight=100.0,                            # density mixing weight
                   beta_m=0.01,                # linear magnetic mixing coefficient
                   nmaxold_m=8,                    # of old magnetic densities used
                   weight_m=100.0),                # magnetic density mixing weight
    maxiter=1500,                        # Set the maximum number of SCF iterations
    txt=f'gs.txt',                                               # output .txt file
    convergence={                                            # convergence criteria
        'eigenstates': 1.0e-10,                                   # eV^2 / electron
        'density': 1.0e-5,                                   # electrons / electron
        'energy': 1.0e-6},                                          # eV / electron
    poissonsolver = PoissonSolver(dipolelayer='xy', name='fd', relax='GS'))

# Get ground state dft energy
sys.calc = dft
dft_gs = sys.get_potential_energy()
sys.calc.write('gs.gpw', mode='all')

# Calculate the diabatic coupling
odc  = CouplingParameters(cdft_a=cdfti, cdft_b=cdftf, AE=False)   # pseudo orbitals
H12  = odc.get_coupling_term()                           # use original CDFT method
modc = CouplingParameters(cdft_a=cdfti, cdft_b=cdftf, calc_gs=dft, AE=False)
Hab  = modc.get_migliore_coupling()                       # use overlap CDFT method

# Write to diabatic coupling file
with open(fp, "w") as file:
    file.write(f"Initial State Energy          = {cdft_i:.6f} eV\n")
    file.write(f"Final State Energy            = {cdft_f:.6f} eV\n")
    file.write(f"Ground State Energy           = {dft_gs:.6f} eV\n")
    file.write(f"Original CDFT Coupling Energy = {H12:.6f} eV\n")
    file.write(f"Migliore Coupling Energy      = {Hab:.6f} eV\n")
#==================================================================================
